// design-lint: allow-file — brand colours are the services' own, not the app's palette.
/**
 * Logos of the services the "/" menu embeds, in their own colours, as small inline SVGs. They are trademarks of
 * their owners, used only to identify each service next to its embed. The marks are the services' official
 * logos: Google Drive, Google Maps and Figma in their multi-colour versions; the rest as Simple Icons draws them
 * (simpleicons.org, CC0) in the brand colour. Single-colour black marks (X, GitHub, CodeSandbox) take the text
 * colour, so they stay visible in dark mode.
 */
import { cn } from 'cn'
import type { ReactNode, SVGProps } from 'react'

export type LogoProps = Omit<SVGProps<SVGSVGElement>, 'ref'> & { size?: number | string }

function logo(name: string, viewBox: string, paths: ReactNode, monochrome = false) {
  function Logo({ size = 18, className, ...rest }: LogoProps) {
    return (
      <svg
        viewBox={viewBox}
        width={size}
        height={size}
        // The menus tint icons with a text colour: a mark in its own colours ignores it; a black one is drawn
        // in the page's text colour.
        className={cn(className, monochrome && 'text-foreground')}
        fill={monochrome ? 'currentColor' : undefined}
        data-logo={name}
        {...rest}
      >
        {paths}
      </svg>
    )
  }
  Logo.displayName = `${name}Logo`
  return Logo
}

